#!/usr/bin/env node
// MIPS32r2 (little-endian, o32) interpreter for doomgeneric_mips.
// Boots DOOM, renders frames, mirrors each drawn frame to /tmp/frame.bmp.
'use strict';
const fs = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Configuration / memory layout
// ---------------------------------------------------------------------------
const ELF_PATH = process.argv[2] || path.join(__dirname, 'doomgeneric_mips');
const MEM_SIZE = 0x40800000;          // covers text/data/bss(1GB heap) + stack
const STACK_TOP = 0x40700000;         // above bss end (~0x404b1790)
const GP_VALUE = 0x0047d090;          // _gp from map

// symbol addresses (from doomgeneric_mips.map)
const DRAWFRAME_ADDR = 0x004395e4;    // DG_DrawFrame entry
const SCREENBUF_PTR  = 0x004b0a40;    // &DG_ScreenBuffer (pointer global)
const RESX = 640, RESY = 400;

const mem = new Uint8Array(MEM_SIZE);
const dv = new DataView(mem.buffer);

// ---------------------------------------------------------------------------
// ELF loader
// ---------------------------------------------------------------------------
function loadElf(file) {
  const buf = fs.readFileSync(file);
  if (buf[0] !== 0x7f || buf[1] !== 0x45) throw new Error('not ELF');
  const entry = buf.readUInt32LE(24);
  const phoff = buf.readUInt32LE(28);
