// ---------------------------------------------------------------------------
// Frame dump: reproduce writeBMPFile() output byte-exactly from DG_ScreenBuffer
// ---------------------------------------------------------------------------
function dumpFrame() {
  const ptr = u32(SCREENBUF_PTR);
  if (!ptr) return;
  const imgSize = RESX * RESY * 4;
  const fileSize = 54 + imgSize;
  const out = Buffer.alloc(fileSize);
  out[0] = 0x42; out[1] = 0x4d;          // 'BM'
  out.writeUInt32LE(fileSize, 2);
  out.writeUInt32LE(0, 6);
  out.writeUInt32LE(54, 10);
  out.writeUInt32LE(40, 14);
  out.writeInt32LE(RESX, 18);
  out.writeInt32LE(-RESY, 22);
  out.writeUInt16LE(1, 26);
  out.writeUInt16LE(32, 28);
  out.writeUInt32LE(0, 30);
  out.writeUInt32LE(imgSize, 34);
  // remaining header fields already zero
  // pixels copied verbatim (guest is LE, buffer is uint32[] -> raw bytes)
  const start = ptr >>> 0;
  Buffer.from(mem.subarray(start, start + imgSize)).copy(out, 54);
  fs.writeFileSync('/tmp/frame.bmp', out);
